window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["tesla"]={html:"<div class=\"own-tesla\">\n  <header class=\"ts-bar\">\n    <a class=\"ts-wordmark\" href=\"#ts-top\">Northwind</a>\n    <nav class=\"ts-nav\" aria-label=\"Primary\">\n      <a href=\"#ts-models\">Dashboards</a>\n      <a href=\"#ts-regions\">Regions</a>\n      <a href=\"#ts-throughput\">Throughput</a>\n      <a href=\"#ts-discover\">Discover</a>\n      <a href=\"#ts-shop\">Shop</a>\n    </nav>\n    <div class=\"ts-icons\" aria-label=\"Utility\">\n      <a class=\"ts-icon\" href=\"#\" aria-label=\"Help\">?</a>\n      <a class=\"ts-icon\" href=\"#\" aria-label=\"Language\">Globe</a>\n      <a class=\"ts-icon\" href=\"#\" aria-label=\"Account\">Acct</a>\n    </div>\n  </header>\n\n  <section class=\"ts-hero\" id=\"ts-top\" aria-labelledby=\"ts-hero-h\">\n    <div class=\"ts-scene\" aria-hidden=\"true\">\n      <div class=\"ts-sky\"></div>\n      <div class=\"ts-city\"></div>\n      <div class=\"ts-ground\"></div>\n      <svg class=\"ts-car\" viewBox=\"0 0 640 220\" preserveAspectRatio=\"xMidYMax meet\">\n        <path d=\"M40 160c0-16 12-26 30-30l70-10c22-26 52-42 96-42s74 16 96 42l70 10c18 4 30 14 30 30v14c0 8-6 14-14 14H54c-8 0-14-6-14-14z\" fill=\"#26282e\"/>\n        <path d=\"M180 118c18-22 42-34 74-34s56 12 74 34z\" fill=\"#9aa0a8\"/>\n        <path d=\"M188 116c16-18 36-28 66-28s50 10 66 28z\" fill=\"#c8ccd2\"/>\n        <rect x=\"250\" y=\"96\" width=\"4\" height=\"22\" fill=\"#26282e\"/>\n        <circle cx=\"150\" cy=\"172\" r=\"26\" fill=\"#111318\"/><circle cx=\"150\" cy=\"172\" r=\"11\" fill=\"#4a4e56\"/>\n        <circle cx=\"500\" cy=\"172\" r=\"26\" fill=\"#111318\"/><circle cx=\"500\" cy=\"172\" r=\"11\" fill=\"#4a4e56\"/>\n        <rect x=\"300\" y=\"176\" width=\"60\" height=\"8\" rx=\"4\" fill=\"#171a20\"/>\n      </svg>\n    </div>\n    <div class=\"ts-hero-copy\">\n      <h1 id=\"ts-hero-h\">Northwind Model X</h1>\n      <p>Regional operations, at the speed of one screen</p>\n      <div class=\"ts-hero-cta\">\n        <a class=\"ts-btn ts-btn-primary\" href=\"#ts-shop\">Order Now</a>\n        <a class=\"ts-btn ts-btn-secondary\" href=\"#ts-models\">View Inventory</a>\n      </div>\n    </div>\n    <div class=\"ts-carousel\" aria-hidden=\"true\">\n      <span class=\"ts-dot on\"></span><span class=\"ts-dot\"></span><span class=\"ts-dot\"></span>\n    </div>\n  </section>\n\n  <section class=\"ts-band\" id=\"ts-throughput\" aria-labelledby=\"ts-band-h\">\n    <div class=\"ts-band-scene\" aria-hidden=\"true\"></div>\n    <div class=\"ts-band-copy\">\n      <h2 id=\"ts-band-h\">Every region, one frame</h2>\n      <p>Track orders, refunds, and delivery times across every storefront without leaving the road view.</p>\n      <div class=\"ts-band-cta\">\n        <a class=\"ts-btn ts-btn-secondary\" href=\"#ts-regions\">Explore Regions</a>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"ts-cards\" id=\"ts-regions\" aria-labelledby=\"ts-cards-h\">\n    <h2 id=\"ts-cards-h\" class=\"ts-visually-hidden\">Featured dashboards</h2>\n    <div class=\"ts-card-grid\">\n      <article class=\"ts-ccard ts-ccard-large\">\n        <div class=\"ts-ccard-scene ts-scene-a\" aria-hidden=\"true\"></div>\n        <span class=\"ts-ccard-label\">Regional throughput</span>\n        <div class=\"ts-ccard-meta\">\n          <p>North and East in one live view</p>\n          <a href=\"#ts-shop\">Order Now</a>\n          <a href=\"#ts-models\">Learn</a>\n        </div>\n      </article>\n      <article class=\"ts-ccard\">\n        <div class=\"ts-ccard-scene ts-scene-b\" aria-hidden=\"true\"></div>\n        <span class=\"ts-ccard-label\">Store scorecards</span>\n        <div class=\"ts-ccard-meta\">\n          <p>Rank every storefront</p>\n          <a href=\"#ts-shop\">Order Now</a>\n          <a href=\"#ts-models\">Learn</a>\n        </div>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"ts-models\" id=\"ts-models\" aria-labelledby=\"ts-models-h\">\n    <h2 id=\"ts-models-h\" class=\"ts-sec-title\">The lineup</h2>\n    <p class=\"ts-sec-sub\">Three surfaces for the same operation &mdash; pick the one you drive.</p>\n    <div class=\"ts-model-grid\">\n      <article class=\"ts-model\">\n        <div class=\"ts-model-art ts-art-a\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 260 120\"><path d=\"M20 92c0-12 9-19 22-22l52-8c16-19 38-31 70-31s54 12 70 31l52 8c13 3 22 10 22 22v11c0 6-5 11-11 11H31c-6 0-11-5-11-11z\" fill=\"#2a2d33\"/><path d=\"M124 52c12-14 28-22 50-22s38 8 50 22z\" fill=\"#b7bcc2\"/><circle cx=\"98\" cy=\"104\" r=\"17\" fill=\"#111318\"/><circle cx=\"352\" cy=\"104\" r=\"17\" fill=\"#111318\"/></svg>\n        </div>\n        <h3>Model S</h3>\n        <div class=\"ts-model-links\"><a href=\"#\">Learn</a><a href=\"#\">Order</a></div>\n      </article>\n      <article class=\"ts-model\">\n        <div class=\"ts-model-art ts-art-b\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 260 120\"><path d=\"M20 92c0-12 9-19 22-22l52-8c16-19 38-31 70-31s54 12 70 31l52 8c13 3 22 10 22 22v11c0 6-5 11-11 11H31c-6 0-11-5-11-11z\" fill=\"#2a2d33\"/><path d=\"M124 52c12-14 28-22 50-22s38 8 50 22z\" fill=\"#b7bcc2\"/><circle cx=\"98\" cy=\"104\" r=\"17\" fill=\"#111318\"/><circle cx=\"352\" cy=\"104\" r=\"17\" fill=\"#111318\"/></svg>\n        </div>\n        <h3>Model 3</h3>\n        <div class=\"ts-model-links\"><a href=\"#\">Learn</a><a href=\"#\">Order</a></div>\n      </article>\n      <article class=\"ts-model\">\n        <div class=\"ts-model-art ts-art-c\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 260 120\"><path d=\"M20 92c0-12 9-19 22-22l52-8c16-19 38-31 70-31s54 12 70 31l52 8c13 3 22 10 22 22v11c0 6-5 11-11 11H31c-6 0-11-5-11-11z\" fill=\"#2a2d33\"/><path d=\"M124 52c12-14 28-22 50-22s38 8 50 22z\" fill=\"#b7bcc2\"/><circle cx=\"98\" cy=\"104\" r=\"17\" fill=\"#111318\"/><circle cx=\"352\" cy=\"104\" r=\"17\" fill=\"#111318\"/></svg>\n        </div>\n        <h3>Model Y</h3>\n        <div class=\"ts-model-links\"><a href=\"#\">Learn</a><a href=\"#\">Order</a></div>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"ts-discover\" id=\"ts-discover\" aria-labelledby=\"ts-disc-h\">\n    <div class=\"ts-disc-copy\">\n      <h2 id=\"ts-disc-h\">Built to be driven, not configured</h2>\n      <p>No charts to wire, no filters to learn. The operation renders itself and gets out of your way.</p>\n    </div>\n    <div class=\"ts-disc-stats\">\n      <div class=\"ts-stat\"><b>99.98%</b><span>Uptime, trailing 90 days</span></div>\n      <div class=\"ts-stat\"><b>184,904</b><span>Orders tracked per day</span></div>\n      <div class=\"ts-stat\"><b>82 ms</b><span>Median query latency</span></div>\n      <div class=\"ts-stat\"><b>4</b><span>Regions on one screen</span></div>\n    </div>\n  </section>\n\n  <section class=\"ts-shop\" id=\"ts-shop\" aria-labelledby=\"ts-shop-h\">\n    <div class=\"ts-shop-copy\">\n      <h2 id=\"ts-shop-h\">Start your operation</h2>\n      <p>Order now and the first store connects in minutes. No card required to begin.</p>\n      <div class=\"ts-shop-cta\">\n        <a class=\"ts-btn ts-btn-primary\" href=\"#\">Order Now</a>\n        <a class=\"ts-btn ts-btn-secondary\" href=\"#\">Schedule a Demo</a>\n      </div>\n    </div>\n    <div class=\"ts-shop-art\" aria-hidden=\"true\">\n      <div class=\"ts-ring\"></div>\n      <div class=\"ts-ring ts-ring-sm\"></div>\n    </div>\n  </section>\n\n  <footer class=\"ts-foot\">\n    <div class=\"ts-foot-grid\">\n      <div class=\"ts-foot-brand\">\n        <span class=\"ts-wordmark ts-wordmark-dark\">Northwind</span>\n        <p>Operations analytics for every region. Sample data, showcase only.</p>\n      </div>\n      <nav class=\"ts-foot-col\" aria-label=\"Product\"><h4>Product</h4><a href=\"#ts-models\">Dashboards</a><a href=\"#ts-regions\">Regions</a><a href=\"#ts-throughput\">Throughput</a></nav>\n      <nav class=\"ts-foot-col\" aria-label=\"Company\"><h4>Company</h4><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Newsroom</a></nav>\n      <nav class=\"ts-foot-col\" aria-label=\"Support\"><h4>Support</h4><a href=\"#\">Contact</a><a href=\"#\">Status</a><a href=\"#\">Security</a></nav>\n    </div>\n    <div class=\"ts-foot-row\">\n      <span>&copy; 2026 Northwind &mdash; fictional brand</span>\n      <span class=\"ts-foot-links\"><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Cookies</a></span>\n    </div>\n  </footer>\n\n  <div class=\"ts-ask\">\n    <div class=\"ts-ask-inner\">\n      <span class=\"ts-ask-icon\" aria-hidden=\"true\">?</span>\n      <span class=\"ts-ask-label\">Ask a Question</span>\n      <input class=\"ts-ask-input\" type=\"text\" placeholder=\"What's throughput?\" aria-label=\"Ask a question\">\n      <button class=\"ts-ask-send\" type=\"button\" aria-label=\"Send\">Send</button>\n      <a class=\"ts-ask-cta\" href=\"#ts-shop\">Schedule a Demo</a>\n    </div>\n  </div>\n</div>\n",css:"/* ══ TESLA — own layout for showcase.html ═══════════════════════════════════\n   Radical subtraction: full-viewport cinematic sections, near-zero UI decoration\n   (no shadows, gradients, or borders), one chromatic accent — Electric Blue for\n   the primary CTA only — Universal Sans substituted with Inter, 4px button radii,\n   and a transparent nav that floats over the hero. Scoped under `.own-tesla`;\n   responsive via @container frame. */\n\n.own-tesla {\n  --ts-blue: #3e6ae1;\n  --ts-blue-hover: #3459c9;\n  --ts-white: #ffffff;\n  --ts-ash: #f4f4f4;\n  --ts-carbon: #171a20;\n  --ts-graphite: #393c41;\n  --ts-pewter: #5c5e62;\n  --ts-silver: #8e8e8e;\n  --ts-cloud: #eeeeee;\n  --ts-pale: #d0d1d2;\n\n  --ts-display: 'Universal Sans Display', -apple-system, BlinkMacSystemFont, Arial, sans-serif;\n  --ts-text: 'Universal Sans Text', -apple-system, BlinkMacSystemFont, Arial, sans-serif;\n\n  position: relative;\n  background: var(--ts-white);\n  color: var(--ts-carbon);\n  font-family: var(--ts-text);\n  font-size: 14px;\n  line-height: 1.43;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n  border-radius: 13px;\n  overflow: clip;\n}\n\n.own-tesla *,\n.own-tesla *::before,\n.own-tesla *::after { box-sizing: border-box; }\n\n.own-tesla :focus-visible { outline: 2px solid var(--ts-blue); outline-offset: 2px; border-radius: 4px; }\n\n.own-tesla h1, .own-tesla h2, .own-tesla h3, .own-tesla h4 { margin: 0; font-weight: 500; letter-spacing: normal; line-height: 1.2; }\n.own-tesla p { margin: 0; }\n.own-tesla a { color: inherit; text-decoration: none; }\n.own-tesla .ts-visually-hidden {\n  position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;\n}\n\n/* ── buttons — barely-rounded rectangles ──────────────────────────────────── */\n.own-tesla .ts-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  font-family: var(--ts-text); font-weight: 500; font-size: 14px; line-height: 1.2;\n  min-height: 40px; min-width: 200px; padding: 4px 16px; border-radius: 4px;\n  border: 3px solid transparent; cursor: pointer; white-space: nowrap;\n  transition: border-color .33s, background-color .33s, color .33s, box-shadow .25s;\n}\n.own-tesla .ts-btn-primary { background: var(--ts-blue); color: #fff; }\n.own-tesla .ts-btn-primary:hover { background: var(--ts-blue-hover); }\n.own-tesla .ts-btn-secondary { background: #fff; color: var(--ts-graphite); }\n.own-tesla .ts-btn-secondary:hover { background: var(--ts-ash); }\n\n/* ── nav — transparent, floats over the hero ──────────────────────────────── */\n.own-tesla .ts-bar {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 24px;\n  padding: 0 32px; height: 56px; margin-bottom: -56px;\n  background: rgba(255, 255, 255, .75);\n  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);\n}\n.own-tesla .ts-wordmark { font-size: 20px; font-weight: 500; letter-spacing: .28em; color: var(--ts-carbon); }\n.own-tesla .ts-wordmark-dark { color: var(--ts-carbon); letter-spacing: .04em; font-size: 20px; }\n.own-tesla .ts-nav { display: flex; align-items: center; gap: 4px; margin: 0 auto; }\n.own-tesla .ts-nav a {\n  font-size: 14px; font-weight: 500; color: var(--ts-carbon); padding: 4px 16px; min-height: 32px;\n  display: inline-flex; align-items: center; border-radius: 4px; transition: background-color .33s, color .33s;\n}\n.own-tesla .ts-nav a:hover { background: rgba(0, 0, 0, .05); }\n.own-tesla .ts-icons { display: flex; align-items: center; gap: 6px; margin-left: auto; }\n.own-tesla .ts-icon {\n  display: inline-flex; align-items: center; justify-content: center; height: 32px; padding: 0 12px;\n  font-size: 12px; font-weight: 500; color: var(--ts-carbon); border-radius: 4px;\n}\n.own-tesla .ts-icon:hover { background: rgba(0, 0, 0, .05); }\n\n/* ── hero — full-viewport cinematic scene ─────────────────────────────────── */\n.own-tesla .ts-hero {\n  position: relative; display: flex; flex-direction: column; justify-content: center;\n  min-height: clamp(500px, 84vh, 720px); overflow: clip; isolation: isolate;\n}\n.own-tesla .ts-scene { position: absolute; inset: 0; z-index: -1; }\n.own-tesla .ts-sky {\n  position: absolute; inset: 0;\n  background: linear-gradient(180deg, #c9d2dc 0%, #dde3ea 45%, #eef0f2 72%, #e6e8ea 100%);\n}\n.own-tesla .ts-city {\n  position: absolute; left: 0; right: 0; bottom: 34%;\n  height: 26%;\n  background:\n    repeating-linear-gradient(90deg,\n      transparent 0 26px, #b9c2cc 26px 58px, transparent 58px 74px, #c4ccd5 74px 96px, transparent 96px 130px);\n  -webkit-mask-image: linear-gradient(180deg, #000, rgba(0, 0, 0, .4));\n  mask-image: linear-gradient(180deg, #000, rgba(0, 0, 0, .4));\n  opacity: .8;\n}\n.own-tesla .ts-ground {\n  position: absolute; left: 0; right: 0; bottom: 0; height: 34%;\n  background: linear-gradient(180deg, #4c4e52 0%, #3a3c40 100%);\n}\n.own-tesla .ts-car { position: absolute; left: 50%; bottom: 4%; width: min(640px, 78%); transform: translateX(-50%); }\n.own-tesla .ts-hero-copy {\n  position: relative; z-index: 1; text-align: center; padding: 0 24px;\n  display: flex; flex-direction: column; align-items: center;\n}\n.own-tesla .ts-hero h1 {\n  font-family: var(--ts-display); font-size: 40px; font-weight: 500; line-height: 1.2; color: #fff;\n  text-shadow: 0 1px 24px rgba(0, 0, 0, .28); margin-bottom: 8px;\n}\n.own-tesla .ts-hero-copy > p { font-size: 17px; font-weight: 500; color: rgba(255, 255, 255, .92); margin-bottom: 22px; text-shadow: 0 1px 16px rgba(0, 0, 0, .3); }\n.own-tesla .ts-hero-cta { display: flex; flex-wrap: wrap; gap: 16px; justify-content: center; }\n.own-tesla .ts-carousel { position: absolute; left: 0; right: 0; bottom: 22px; display: flex; gap: 8px; justify-content: center; z-index: 1; }\n.own-tesla .ts-dot { width: 8px; height: 8px; border-radius: 50%; background: rgba(255, 255, 255, .45); }\n.own-tesla .ts-dot.on { background: #fff; }\n\n/* ── feature band — full-bleed scene, light copy on dark ──────────────────── */\n.own-tesla .ts-band {\n  position: relative; display: flex; align-items: center; min-height: clamp(440px, 70vh, 620px);\n  padding: 64px 40px; overflow: clip; isolation: isolate;\n}\n.own-tesla .ts-band-scene {\n  position: absolute; inset: 0; z-index: -1;\n  background:\n    linear-gradient(180deg, #1b1d22 0%, #24262b 55%, #2c2f35 100%);\n}\n.own-tesla .ts-band-scene::after {\n  content: ''; position: absolute; inset: 0;\n  background:\n    radial-gradient(40% 60% at 70% 30%, rgba(62, 106, 225, .22), transparent 70%),\n    repeating-linear-gradient(115deg, transparent 0 40px, rgba(255, 255, 255, .03) 40px 42px);\n}\n.own-tesla .ts-band-copy { max-width: 46ch; }\n.own-tesla .ts-band h2 { font-family: var(--ts-display); font-size: 34px; font-weight: 500; color: #fff; margin-bottom: 12px; }\n.own-tesla .ts-band p { font-size: 14px; font-weight: 400; line-height: 1.6; color: rgba(255, 255, 255, .82); margin-bottom: 22px; }\n\n/* ── category cards — 2-up, rounded full-bleed scenes ─────────────────────── */\n.own-tesla .ts-cards { padding: 16px; }\n.own-tesla .ts-card-grid { display: grid; grid-template-columns: 1.35fr 1fr; gap: 16px; }\n.own-tesla .ts-ccard {\n  position: relative; border-radius: 12px; overflow: hidden; min-height: 380px;\n  display: flex; flex-direction: column; justify-content: space-between; padding: 24px; isolation: isolate;\n}\n.own-tesla .ts-ccard-scene { position: absolute; inset: 0; z-index: -1; }\n.own-tesla .ts-scene-a {\n  background: linear-gradient(180deg, #cbd4de 0%, #b3c0cd 58%, #59626c 59%, #3f454c 100%);\n}\n.own-tesla .ts-scene-a::after {\n  content: ''; position: absolute; left: 12%; bottom: 20%; width: 76%; height: 22%;\n  border-radius: 50% 50% 8px 8px; background: rgba(30, 33, 38, .42);\n}\n.own-tesla .ts-scene-b {\n  background: linear-gradient(180deg, #dfe3e8 0%, #c6ccd3 60%, #4a4f56 61%, #34383e 100%);\n}\n.own-tesla .ts-ccard-label {\n  align-self: flex-start; font-size: 16px; font-weight: 500; color: #fff; text-shadow: 0 1px 12px rgba(0, 0, 0, .4);\n}\n.own-tesla .ts-ccard-meta { display: flex; flex-direction: column; gap: 8px; }\n.own-tesla .ts-ccard-meta p { font-size: 14px; color: rgba(255, 255, 255, .92); text-shadow: 0 1px 12px rgba(0, 0, 0, .4); }\n.own-tesla .ts-ccard-meta > a {\n  align-self: flex-start; font-size: 14px; font-weight: 400; color: #fff; text-shadow: 0 1px 12px rgba(0, 0, 0, .4);\n}\n.own-tesla .ts-ccard-meta > a:hover { text-decoration: underline; }\n\n/* ── model lineup — white, transparent car SVGs, no borders ───────────────── */\n.own-tesla .ts-models { padding: 72px 40px; text-align: center; }\n.own-tesla .ts-sec-title { font-family: var(--ts-display); font-size: 34px; font-weight: 500; }\n.own-tesla .ts-sec-sub { font-size: 14px; color: var(--ts-graphite); margin-top: 10px; }\n.own-tesla .ts-model-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 44px; }\n.own-tesla .ts-model { display: flex; flex-direction: column; align-items: center; gap: 12px; }\n.own-tesla .ts-model-art { width: 100%; max-width: 300px; }\n.own-tesla .ts-model-art svg { width: 100%; height: auto; display: block; }\n.own-tesla .ts-model h3 { font-family: var(--ts-text); font-size: 17px; font-weight: 500; }\n.own-tesla .ts-model-links { display: flex; gap: 24px; }\n.own-tesla .ts-model-links a { font-size: 14px; font-weight: 400; color: var(--ts-pewter); }\n.own-tesla .ts-model-links a:hover { color: var(--ts-carbon); text-decoration: underline; }\n\n/* ── discover — white stats band ──────────────────────────────────────────── */\n.own-tesla .ts-discover {\n  display: grid; grid-template-columns: 1fr 1.2fr; gap: 48px; align-items: center;\n  padding: 72px 40px; background: var(--ts-ash);\n}\n.own-tesla .ts-discover h2 { font-family: var(--ts-display); font-size: 34px; font-weight: 500; margin-bottom: 12px; max-width: 18ch; }\n.own-tesla .ts-discover p { font-size: 14px; line-height: 1.6; color: var(--ts-graphite); max-width: 42ch; }\n.own-tesla .ts-disc-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 28px 40px; }\n.own-tesla .ts-stat { display: grid; gap: 4px; }\n.own-tesla .ts-stat b { font-family: var(--ts-display); font-size: 34px; font-weight: 500; color: var(--ts-carbon); font-variant-numeric: tabular-nums; }\n.own-tesla .ts-stat span { font-size: 14px; color: var(--ts-pewter); }\n\n/* ── shop CTA ─────────────────────────────────────────────────────────────── */\n.own-tesla .ts-shop {\n  position: relative; display: flex; align-items: center; justify-content: space-between; gap: 32px;\n  min-height: clamp(360px, 56vh, 520px); padding: 72px 40px; overflow: clip; isolation: isolate;\n  background: linear-gradient(180deg, #f7f8f9 0%, #eceef0 100%);\n}\n.own-tesla .ts-shop-copy { max-width: 42ch; }\n.own-tesla .ts-shop h2 { font-family: var(--ts-display); font-size: 34px; font-weight: 500; margin-bottom: 12px; }\n.own-tesla .ts-shop p { font-size: 14px; line-height: 1.6; color: var(--ts-graphite); margin-bottom: 22px; }\n.own-tesla .ts-shop-cta { display: flex; flex-wrap: wrap; gap: 16px; }\n.own-tesla .ts-shop-art { position: relative; width: 300px; height: 220px; flex: none; }\n.own-tesla .ts-ring {\n  position: absolute; inset: 0; border-radius: 50%;\n  border: 26px solid rgba(62, 106, 225, .14);\n}\n.own-tesla .ts-ring-sm { inset: 28%; border-width: 18px; border-color: rgba(62, 106, 225, .28); }\n\n/* ── footer ───────────────────────────────────────────────────────────────── */\n.own-tesla .ts-foot { padding: 64px 40px 32px; background: #fff; }\n.own-tesla .ts-foot-grid { display: grid; grid-template-columns: 1.6fr repeat(3, 1fr); gap: 32px; max-width: 1200px; margin: 0 auto; }\n.own-tesla .ts-foot-brand p { font-size: 13px; color: var(--ts-pewter); margin-top: 12px; max-width: 32ch; line-height: 1.6; }\n.own-tesla .ts-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-tesla .ts-foot-col h4 { font-size: 14px; font-weight: 500; }\n.own-tesla .ts-foot-col a { font-size: 14px; font-weight: 400; color: var(--ts-pewter); }\n.own-tesla .ts-foot-col a:hover { color: var(--ts-carbon); text-decoration: underline; }\n.own-tesla .ts-foot-row {\n  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  max-width: 1200px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--ts-cloud);\n  font-size: 13px; color: var(--ts-pewter);\n}\n.own-tesla .ts-foot-links { display: flex; gap: 18px; }\n.own-tesla .ts-foot-links a:hover { color: var(--ts-carbon); }\n\n/* ── persistent ask bar (sticky, not fixed) ───────────────────────────────── */\n.own-tesla .ts-ask {\n  position: sticky; bottom: 0; z-index: 35; padding: 0 16px 16px;\n  pointer-events: none;\n}\n.own-tesla .ts-ask-inner {\n  pointer-events: auto;\n  display: flex; align-items: center; gap: 14px;\n  max-width: 1200px; margin: 0 auto; padding: 10px 14px;\n  background: #fff; border: 1px solid var(--ts-cloud); border-radius: 8px;\n}\n.own-tesla .ts-ask-icon {\n  display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%;\n  background: var(--ts-ash); color: var(--ts-graphite); font-size: 13px; font-weight: 500; flex: none;\n}\n.own-tesla .ts-ask-label { font-size: 14px; font-weight: 500; color: var(--ts-carbon); white-space: nowrap; }\n.own-tesla .ts-ask-input {\n  flex: 1; min-width: 0; font-family: var(--ts-text); font-size: 14px; color: var(--ts-carbon);\n  border: 0; background: transparent; padding: 6px 4px;\n}\n.own-tesla .ts-ask-input::placeholder { color: var(--ts-silver); }\n.own-tesla .ts-ask-input:focus { outline: none; }\n.own-tesla .ts-ask-send {\n  font-family: var(--ts-text); font-size: 14px; font-weight: 500; color: var(--ts-carbon);\n  background: transparent; border: 0; cursor: pointer; padding: 6px 8px; border-radius: 4px;\n}\n.own-tesla .ts-ask-send:hover { background: var(--ts-ash); }\n.own-tesla .ts-ask-cta { font-size: 14px; font-weight: 500; color: var(--ts-carbon); white-space: nowrap; }\n.own-tesla .ts-ask-cta::before { content: ''; display: inline-block; width: 16px; height: 16px; margin-right: 7px; border-radius: 4px; background: var(--ts-blue); vertical-align: -3px; }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-tesla .ts-nav { display: none; }\n  .own-tesla .ts-card-grid { grid-template-columns: 1fr; }\n  .own-tesla .ts-ccard { min-height: 320px; }\n  .own-tesla .ts-model-grid { grid-template-columns: 1fr 1fr; }\n  .own-tesla .ts-model:last-child { display: none; }\n  .own-tesla .ts-discover { grid-template-columns: 1fr; gap: 32px; }\n  .own-tesla .ts-foot-grid { grid-template-columns: 1fr 1fr; gap: 24px; }\n}\n@container frame (max-width: 760px) {\n  .own-tesla .ts-bar { top: 10px; height: 52px; padding: 0 16px; }\n  .own-tesla .ts-wordmark { font-size: 17px; letter-spacing: .2em; }\n  .own-tesla .ts-icon { display: none; }\n  .own-tesla .ts-hero h1 { font-size: 30px; }\n  .own-tesla .ts-hero-cta { flex-direction: column; width: 100%; max-width: 320px; }\n  .own-tesla .ts-btn { width: 100%; }\n  .own-tesla .ts-band,\n  .own-tesla .ts-models,\n  .own-tesla .ts-discover,\n  .own-tesla .ts-shop,\n  .own-tesla .ts-foot { padding-left: 18px; padding-right: 18px; }\n  .own-tesla .ts-discover h2,\n  .own-tesla .ts-shop h2,\n  .own-tesla .ts-sec-title { font-size: 28px; }\n  .own-tesla .ts-model-grid { grid-template-columns: 1fr 1fr; gap: 20px; }\n  .own-tesla .ts-model:last-child { display: flex; }\n  .own-tesla .ts-shop { flex-direction: column; align-items: flex-start; }\n  .own-tesla .ts-shop-art { display: none; }\n  .own-tesla .ts-ask-label { display: none; }\n  .own-tesla .ts-ask-cta { display: none; }\n}\n@container frame (max-width: 430px) {\n  .own-tesla .ts-model-grid { grid-template-columns: 1fr; }\n  .own-tesla .ts-disc-stats { grid-template-columns: 1fr; gap: 20px; }\n  .own-tesla .ts-foot-grid { grid-template-columns: 1fr; }\n  .own-tesla .ts-ask-inner { gap: 10px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-tesla *, .own-tesla *::before, .own-tesla *::after {\n    transition-duration: .001ms !important;\n    animation-duration: .001ms !important;\n  }\n}\n"};
/* ══ TESLA — behaviour for showcase.html ════════════════════════════════════
   Registers window.OWN_LAYOUTS['tesla'].init(root). Tesla's interactions are
   colour-only (no scale/translate), so the script stays minimal: the hero
   carousel dots cycle on a slow interval and the "Ask a Question" bar submits
   to nothing (sample). The interval and listeners are cleared in cleanup. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['tesla'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var timer = null;

      var dots = root.querySelectorAll('.ts-dot');
      var active = 0;

      function paint() {
        dots.forEach(function (d, i) { d.classList.toggle('on', i === active); });
      }

      if (!reduced && dots.length > 1) {
        timer = setInterval(function () {
          active = (active + 1) % dots.length;
          paint();
        }, 3800);
      }

      var input = root.querySelector('.ts-ask-input');
      var send = root.querySelector('.ts-ask-send');
      function submit() {
        if (!input) return;
        input.value = '';
        input.placeholder = 'Thanks — a specialist will follow up.';
      }
      if (send) send.addEventListener('click', submit, signal ? { signal: signal } : undefined);
      if (input) input.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') { e.preventDefault(); submit(); }
      }, signal ? { signal: signal } : undefined);

      return function cleanup() {
        if (timer) clearInterval(timer);
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
